def solve(x, y, k):
    if x > y:
        x, y = y, x

    if x == y:
        return 0 if k >= 1 else float('inf')

    if x > y + k:
        return float('inf')

    ans = float('inf')
    for i in range(1, min(x, k) + 1):
        pick_key = solve(x - i, y, k - i)
        if pick_key != float('inf'):
            ans = min(ans, pick_key + 1)
    for i in range(1, min(y, k) + 1):
        pick_chest = solve(x, y - i, k - i)
        if pick_chest != float('inf'):
            ans = min(ans, pick_chest + i)

    return ans

