import sys

def bfs(x, y, k, visited, moves):
    queue = deque([(x, y, 0)])
    visited[(x, y)] = True
    while queue:
        pos, key_pos, time = queue.popleft()
        if pos == key_pos:
            return time
        for dx in [-1, 1]:
            nx = pos + dx
            if 0 < nx <= 100 and not visited[(nx, pos)]:
                visited[(nx, pos)] = True
                queue.append((nx, pos, time + 1))
            if 0 < pos - dx <= 100 and pos - dx != key_pos and not visited[(pos - dx, pos)]:
                visited[(pos - dx, pos)] = True
                if k >= time + 1:
                    queue.append((key_pos, pos, time + 1))
                    k -= time + 1
                else:
                    moves.append((pos - dx, pos, time + 1))
                    break
    return -1

