                update(i, -a[i - 1])
                for j in range(i + (i & -i), n + 1, i):
                    a[j - i] = max(a[j - i], sum_range(j, n) - sum_range(j - i, n))
                update(i, a[i - 1])

        for m in range(int(math.log2(n)) + 1):
            for i in range(1 << m, n + 1, 1 << m):
                update(i, -a[i - 1])
                for j in range(i + (i & -i), n + 1, i):
                    a[j - i] = max(a[j - i], sum_range(j, n) - sum_range(j - i, n))
