    n, k, x = map(int, input().split())
    dp = [-1] * (x + 1)
    dp[0] = 0
    for i in range(1, x + 1):
        dp[i] = i

    for _ in range(2, n + 1):
        for j in range(k, x + 1):
            if dp[j - k] != -1:
                dp[j] = max(dp[j], dp[j - k] + j)

    if max(dp[k:]) != -1:
        print(max(dp[k:]))
    else:
        print(-1)

