from typing import List

def solve(A: List[int]):
    n = len(A)
    pos_prod = 1
    neg_prod = 1
    neg_indices = []

    for i in range(n):
        if A[i] > 0:
            pos_prod *= A[i]
        elif A[i] < 0:
            neg_prod *= A[i]
            neg_indices.append(i)

    if pos_prod == 0:
        return 0

    for i in range(len(neg_indices) - 1):
        j = neg_indices[i + 1]
        if A[neg_indices[i]] * A[j] == 1:
            for k in range(i + 1, j):
                A[neg_indices[k]] *= -1
            for k in range(i, j - 1, -1):
                A[neg_indices[k]] *= -1
            break

    A[neg_indices[-1]] *= -1
    return n - pos_prod.bit_length() - len(neg_indices)

