    arr = list(map(int, input().split()))

    pos_prod = 1
    neg_prod = 1
    for num in arr:
        if num > 0:
            pos_prod *= num
        elif num < 0:
            neg_prod *= -num

    operations = 0
    while pos_prod * neg_prod != 0:
        if pos_prod != 1:
            pos_prod //= 2
            operations += 1
        if neg_prod != 1:
            neg_prod *= -2
            operations += 1

    return operations

