def solve():
    n = int(input())
    arr = list(map(int, input().split()))

    pos_prod = 1
    neg_prod = 1
    for num in arr:
        if num > 0:
            pos_prod *= num
        elif num < 0:
            neg_prod *= -num

    if pos_prod == 0:
        return 0

    min_val = min(abs(num) for num in arr)
    operations = 0

    if pos_prod % 2 == 1:
        # If there is an odd number of positive numbers, we need to make one of them zero
        for num in arr:
            if num > 0:
                if num == min_val:
                    operations += abs(num)
                    break

    if neg_prod > 1:
        # If there are multiple negative numbers, we need to make them all zero
        for num in arr:
            if num < 0:
                operations += abs(num)

    return operations

