def solve():
    for perm in permutations(range(1, 10)):
        num = int(''.join(map(str, perm)))
        if num < 2 or num > 987654321:
            continue
        if is_prime(num):
            print(num)
            return
        for i in range(len(str(num)) - 1, 0, -1):
            if num - 10 * (perm[i] - 1) >= 10 * (perm[i - 1] - 1):
                num -= 10 * (perm[i] - 1)
                perm[i - 1] -= 1
                if is_prime(num):
                    print(''.join(map(str, perm)))
                    return
            num += 10 * (perm[i] - 1)
    print(-1)

from math import gcd

def gcd_extended(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = gcd_extended(b % a, a)
        return (g, x - (b // a) * y, y)

def prime_deletion(s):
    if len(s) == 2:
        return -1

    digits = list(map(int, s))
    for i in range(len(digits)):
        for j in range(i+1, len(digits)):
            g, x, y = gcd_extended(digits[i], digits[j])
            if g > 1 and x < 0:
                digits[i], digits[j] = digits[j], digits[i]
                break

    for digit in digits:
        if digit == 1 or digit == 2:
            continue
        for i in range(len(digits)):
            if digits[i] == digit:
                del digits[i]
                break
        else:
            digits.append(digit)
            digits.sort()
            digits = digits[:10]
            break

    if len(digits) == 2:
        return -1

    for i in range(len(digits) - 1):
        if digits[i] + digits[i+1] <= 3 or digits[i] * digits[i+1] > 99:
            return digits

    return digits

def solve():
    t = int(input())
    for _ in range(t):
        s = input()
        print(prime_deletion(s))

