import math

def sieve_of_eratosthenes(limit):
    primes = [True] * (limit + 1)
    primes[0], primes[1] = False, False
    for i in range(2, int(math.sqrt(limit)) + 1):
        if primes[i]:
            for j in range(i * i, limit + 1, i):
                primes[j] = False
    return primes

def find_partition(a, primes):
    n = len(a)
    b, c, used = [], [], [False] * n

    def dfs(i, cur_len, cur_sum):
        if cur_len > n:
            return
        if cur_len == n:
            if all(not any(cur_sum % b[j] for j in range(cur_len))):
                return b, c
        for j in range(i, n):
            if not used[j] and primes[a[j]] and not any(a[j] % b[k] for k in range(cur_len)):
                used[j] = True
                dfs(j + 1, cur_len + 1, cur_sum + a[j])
                used[j] = False

    dfs(0, 0, 0)

    if len(b) == 0:
        return -1
    return b, c

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        primes = sieve_of_eratosthenes(max(a))
        b, c = find_partition(a, primes)
        if b:
            print(len(b), len(c))
            print(*b)
            print(*c)
        else:
            print(-1)

