def find(x):
    if x != parents[x]:
        parents[x] = find(parents[parents[x]])
    return parents[x]

def union(x, y):
    root_x = find(x)
    root_y = find(y)

    if root_x == root_y:
        return False

    if size[root_x] < size[root_y]:
        parents[root_x] = root_y
        size[root_y] += size[root_x]
    else:
        parents[root_y] = root_x
        size[root_x] += size[root_y]

    return True

