import collections

def bfs(a):
    n = len(a)
    graph = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if (a[i] & 1) == (a[j] & 1):
                graph[i].append(j)
                graph[j].append(i)

    q = collections.deque([(0, [])])
    visited = [False] * n
    while q:
        i, path = q.popleft()
        if visited[i]:
            continue
        visited[i] = True
        if path and path[-1] + 1 == a[i]:
            return True
        for j in graph[i]:
            q.append((j, path + [i]))
    return False

