import bisect

def solve(n, m, k, H, heights):
    heights.sort()
    conversations = 0
    for height in heights:
        left = bisect.bisect_left(heights, height - H)
        right = bisect.bisect_right(heights, height + H)
        if left < right:
            conversations += right - left
    return conversations

import bisect

def solve(n, m, k, H, heights):
    heights.sort()
    conversations = 0
    for height in heights:
        left_idx = bisect.bisect_left(heights, height - H)
        right_idx = bisect.bisect_right(heights, height + H)
        if left_idx < right_idx:
            conversations += right_idx - left_idx
    return conversations

from math import gcd

def solve(n, m, k, H, heights):
    steps = [i * k for i in range(1, m + 1)]
    heights_diff = [abs(h - step) for h in heights for step in steps]
    gcds = [gcd(h, g) for h in heights_diff for g in heights_diff if h != g]
    return len([g for g in gcds if g <= k])

