def neighbors(x, y):
    return [(x + dx, y + dy) for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]]

def dfs(x, y, grid, word, visited):
    if not grid[x][y] or (x, y) in visited:
        return
    visited.add((x, y))
    word += grid[x][y]
    for nx, ny in neighbors(x, y):
        dfs(nx, ny, grid, word, visited)

