def solve(n, k, x):
    dp = [[0] * (n + 1) for _ in range(k + 1)]
    for i in range(1, k + 1):
        if i != x:
            dp[i][i] = 1
    for i in range(1, k + 1):
        for j in range(i + 1, n + 1):
            for c in range(1, min(i, j) + 1):
                if i - c >= 1 and j - c >= 1 and j - i + c < k + 1 and j - i + c != x:
                    dp[i][j] += dp[i - c][j - c]
    m = min(range(1, k + 1), key=lambda i: dp[i][n] if i != x else float('inf'))
    if dp[m][n] == 0:
        return "NO"
    return "\n".join(map(str, deque(filter(lambda i: i != x, range(1, k + 1)), default_factory=deque).sample(m))) + "\n" + str(m)

