from typing import List

class SegmentTree:
    def __init__(self, arr: List[int]):
        n = len(arr)
        self.size = 2 ** (n.bit_length() + 1)
        self.tree = [0] * self.size
        self.build(arr, 1, 0, n - 1)

    def build(self, arr: List[int], node: int, start: int, end: int):
        if start == end:
            self.tree[node] = arr[start]
            return
        mid = (start + end) // 2
        self.build(arr, 2 * node, start, mid)
        self.build(arr, 2 * node + 1, mid + 1, end)
        self.tree[node] = self.tree[2 * node] * self.tree[2 * node + 1]

    def update(self, node: int, start: int, end: int, idx: int, val: int):
        if idx < start or end < idx:
            return
        if start == end:
            self.tree[node] = val
            return
        mid = (start + end) // 2
        self.tree[node] = self.tree[2 * node] * self.tree[2 * node + 1]
        self.tree[2 * node] = val if start <= idx <= mid else self.tree[2 * node]
        self.tree[2 * node + 1] = val if idx > mid else self.tree[2 * node + 1]
        self.tree[node] = self.tree[2 * node] * self.tree[2 * node + 1]

    def query(self, node: int, start: int, end: int, l: int, r: int):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        return self.query(2 * node, start, mid, l, r) * self.query(2 * node + 1, mid + 1, end, l, r)

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        st = SegmentTree(arr)
        max_sum = -(10 ** 18)
        min_ops = float('inf')
        for i in range(n):
            st.update(1, 1, n, -arr[i])
            sum_ = st.query(1, 1, n, 1, n)
            if sum_ > max_sum:
                max_sum = sum_
                min_ops = 0
            else:
                min_ops = min(min_ops, n - 1)
        print(max_sum, min_ops)

