                if dp[i - k][j] + a[i] > dp[i][j - k] + b[j]:
                    dp[i - k][j] = float('inf')

    winner = "Tsondu" if dp[n][m] <= 0 else "Tenzing" if dp[0][m] > 0 else "Draw"
    print(winner)

