def prime_factorization(n):
    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def next_prime(n):
    if n % 2 == 0:
        n += 1
    while True:
        n += 2
        is_prime = True
        for p in prime_factorization(n - 4):
            if n % p == 0:
                is_prime = False
                break
        if is_prime:
            break
    return n

