from math import sqrt, factorial, gcd

def solve():
    def lucas(n):
        if n <= 1:
            return 1
        if n % 2 == 0:
            return lucas(n // 2) * lucas(n // 2)
        else:
            return lucas((n - 1) // 2) * lucas((n + 1) // 2) * 2

    def catalan(n):
        return factorial(2 * n) // (factorial(n) * factorial(n + 1) // 2)

    def chocolate_length(n):
        return 4 * lucas(n) - 4 * catalan(n - 1)

    t = int(input())
    for _ in range(t):
        n = int(input())
        print(chocolate_length(n))

