import heapq

def solve(n, t, a, b):
    videos = list(zip(a, b))
    heapq.heapify(videos)

    total_time = 0
    index = 0
    while total_time + videos[index][0] <= t:
        total_time += videos[index][0]
        index += 1

    if index == len(videos):
        return -1

    max_entertainment = max(b[i] for i in range(index))
    for i in range(index - 1, -1, -1):
        if videos[i][1] == max_entertainment:
            return i + 1

import heapq

def solve(n, t, a, b, index, max_entertainment, max_time):
    if index > n:
        return -1

    if max_time < 0:
        return -1

    if max_time >= a[index]:
        max_entertainment = max(max_entertainment, b[index])
        max_time -= a[index]

    heapq.heappush(max_entertainment_heap, (-b[index], index))

    result = solve(n, t, a, b, index + 1, max_entertainment, max_time)

    if result != -1:
        return result

    while max_entertainment_heap and max_time:
        _, index = heapq.heappop(max_entertainment_heap)
        max_time -= 1
        max_entertainment -= b[index]
        result = index

    return result

