import heapq

def solve(a, b):
    # Define the set of reachable points from (0, 0) with at most 2 jumps
    reachable = {(0, 0), (0, 1), (1, 0), (1, 1)}
    queue = [((0, 0), 1)]  # (current position, number of jumps)

    while queue:
        pos, jumps = heapq.heappop(queue)

        if pos[0] == a and pos[1] == b:
            return jumps, pos

        for dx, dy in ((0, 1), (1, 0), (1, 1), (1, -1)):
            x, y = pos[0] + dx, pos[1] + dy
            if 0 <= x <= 10 ** 9 and 0 <= y <= 10 ** 9 and (x, y) not in reachable:
                reachable.add((x, y))
                heapq.heappush(queue, ((x, y), jumps + 1))

    # If no solution is found, return 2 jumps and the point (a, b)
    return 2, (a, b)

import math
import heapq

def manhattan_distance(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def dijkstra(start, end, grid):
    queue = [(0, start)]
    visited = set()
    while queue:
        _, current = heapq.heappop(queue)
        if current in visited:
            continue
        visited.add(current)
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            next_point = (current[0] + dx, current[1] + dy)
            if 0 <= next_point[0] <= 10**9 and 0 <= next_point[1] <= 10**9 and next_point not in visited:
                new_distance = current[0] + 1
                if next_point == end:
                    return new_distance
                heapq.heappush(queue, (new_distance, next_point))

def solve(a, b):
    start = (0, 0)
    end = (a, b)
    if manhattan_distance(start, end) <= 2:
        return 1, start, end
    shortest_distance = dijkstra(start, end, set())
    if shortest_distance <= 2:
        return shortest_distance + 1, (0, 0), (shortest_distance // 2, shortest_distance % 2) if shortest_distance % 2 else (shortest_distance // 2, shortest_distance // 2)
    return 2, (0, 0), (shortest_distance // 2, 0), (shortest_distance // 2, shortest_distance // 2)

from math import gcd

def solve(n, k):
    if gcd(n, k) != 1:
        return "NO"

    if k > n:
        n, k = k, n

    if k == 2:
        return "YES"

    x, y = n // k, n
    while x > y:
        x = (n + k - y) // k
        y = (n + k - x) // k
    if x == y:
        return "YES"
    return "NO"

