        @functools.lru_cache(maxsize=None)
        def dp(i: int) -> int:
            if i == len(num) + 1:
                return 0
            if i == len(num):
                return 10 * digit + int(num)
            return max(
                dp(i + 2) + (10 * digit + int(num[i:])),
