def solve(s):
    if len(s) <= 1:
        return "YES" if s == "0" or s == "1" else "NO"

    # Check if the string can be converted to an alternating binary string
    # by replacing a character with 0 and another character with 1
    for char in set(s):
        new_s = s.replace(char, "0").replace(char, "1")
        if re.match(r"^(?:0|1)*1(?:0|1)*$", new_s):
            return "YES"

    return "NO"

