from collections import Counter
import re

def solve(s):
    count = Counter(s)
    odd_count = sum(1 for k, v in count.items() if v % 2 != 0)
    if odd_count > 1:
        return "NO"

    pattern = re.compile('(.)\1{' + str(min(v for k, v in count.items() if v > 1)) + '}')
    groups = pattern.findall(s)
    for group in groups:
        if len(group) > 1 and group[0] == group[1]:
            return "NO"

    result = ""
    for k, v in count.items():
        result += v * ('0' if v % 2 == 1 else '1')

    return "YES"

from collections import deque

def solve(n, a):
    q = deque(a)
    mihai, bianca = 0, 0

    while len(q) > 1:
        candies = q.popleft()
        if candies % 2 == 0:
            mihai += candies
        else:
            bianca += candies

        if mihai > bianca + 1:
            return "YES"
        elif mihai < bianca:
            q.append(candies)
            mihai = 0
            bianca += candies

    return "YES" if mihai > bianca else "NO"

import math

def solve(n, a):
    total = sum(a)
    if total % 2 == 0:
        return "YES"
    if n % 2 == 1:
        return "NO"

    # Calculate the maximum number of candies that can be moved from one player to another
    max_move = math.ceil(total / 2)

    # Initialize the number of candies for Mihai and Bianca
    mihai = 0
    bianca = 0

    # Iterate through the bags
    for candies in a:
        # If the number of candies is even, Mihai takes the candies
        if candies % 2 == 0:
            mihai += candies
        else:
            bianca += candies

        # Check if Mihai can move candies from Bianca to have more candies
        if mihai < bianca:
            if mihai + max_move >= bianca:
                mihai += max_move
                bianca -= max_move
                max_move = 0
            else:
                max_move -= (bianca - mihai)
                mihai += (bianca - mihai)

    # Check if Mihai has more candies than Bianca after the last move
    if mihai > bianca:
        return "YES"
    return "NO"

