import heapq

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input()
        stack = list(s)
        heapq.heapify(stack)

        for i in range(1, n):
            if stack[i] < stack[i - 1]:
                break

        if i == n:
            print(s)
        else:
            stack[i], stack[0] = stack[0], stack[i]
            heapq.heapify(stack)
            for j in range(i + 1, n):
                heapq.heappush(stack, stack[j])
            del stack[i]
            for j in range(i - 1, -1, -1):
                heapq.heappop(stack)
            print(''.join(stack))

