import collections
import sys

def bfs(board, start, target):
    queue = collections.deque([start])
    visited = {start: 0}

    moves = [(0, 0), (0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        pos = queue.popleft()
        if pos == target:
            return visited[pos]

        for dx, dy in moves:
            next_pos = (pos[0] + dx, pos[1] + dy)
            if -100 <= next_pos[0] <= 100 and -100 <= next_pos[1] <= 100 and next_pos not in visited:
                queue.append(next_pos)
                visited[next_pos] = visited[pos] + 1

    return -1

