def bfs(board_size, start, end):
    queue = collections.deque([(start, [start])])
    visited = set()
    visited.add(start)

    moves = [(0, 0), (0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        pos, path = queue.popleft()

        if pos == end:
            return len(path)

        for dx, dy in moves:
            next_pos = (pos[0] + dx, pos[1] + dy)

            if (next_pos[0] >= -100 and next_pos[0] <= 100) and (next_pos[1] >= -100 and next_pos[1] <= 100) and next_pos not in visited:
                queue.append((next_pos, path + [next_pos]))
                visited.add(next_pos)

    return -1

