import functools

@functools.lru_cache(maxsize=None)
def solve(a, n):
    max_likes = [0] * (n + 1)
    min_likes = [0] * (n + 1)

    for i, val in enumerate(a):
        max_likes[i + 1] = max(max_likes[i] + val, val)
        min_likes[i + 1] = min(min_likes[i] + val, val)

    for i in range(n - 1, -1, -1):
        max_likes[i] = max(max_likes[i], max_likes[i + 1])
        min_likes[i] = min(min_likes[i], min_likes[i + 1])

    return max_likes[1:], min_likes[1:]

