def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        b = list(map(int, input().split()))

        if a[-1] == max(a) and b[-1] == max(b):
            print("Yes")
        elif n == 1:
            print("No")
        else:
            max_a = max(a)
            max_b = max(b)
            if max_a < max_b:
                a[n - 1], b[n - 1] = b[n - 1], a[n - 1]
                solve()
            else:
                max_a_idx = a.index(max_a)
                max_b_idx = b.index(max_b)
                if max_a_idx != max_b_idx:
                    a[max_a_idx], b[max_b_idx] = b[max_b_idx], a[max_a_idx]
                    a[n - 1], b[n - 1] = b[n - 1], a[n - 1]
                    solve()

from collections import deque

def bfs(grid, start, end):
    queue = deque([start])
    visited = set([start])
    while queue:
        current = queue.popleft()
        for dx, dy in ((0, 1), (1, 0), (0, -1), (-1, 0)):
            next_x, next_y = current[0] + dx, current[1] + dy
            if 0 <= next_x < len(grid) and 0 <= next_y < len(grid[0]) and grid[next_x][next_y] == 0 and (next_x, next_y) not in visited:
                queue.append((next_x, next_y))
                visited.add((next_x, next_y))
                if next_x == end[0] and next_y == end[1]:
                    return len(visited) - len(queue) - 1
    return float('inf')

