    start, end = map(tuple, zip(*map(lambda x: (x[0], 0) if x[1] == 0 else (0, x[0]), enumerate(map(tuple, zip(*grid)))))
    visited, path, components = set(), set(), defaultdict(int)

    def dfs(x, y):
        if (x, y) in visited or grid[x][y] == -1:
            return 0
        visited.add((x, y))
        path.add((x, y))
        components[x, y] += 1
        count = 0
        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nx, ny = x + dx, y + dy
            count += dfs(nx, ny)
        components[x, y] -= count
        if (x, y) in path:
            count += 1
        return count

    dfs(start[0], start[1])
    if start in components or end in components:
        return float('inf')

    for x, y in components:
        if start in components[x, y] or end in components[x, y]:
            return components[x, y]

    return -1

