def solve(s):
    if len(s) == 0:
        return 0
    elif len(s) == 1:
        return 1
    else:
        min_len = len(s) * 2
        for i in range(1, len(s)):
            left_part = s[:i]
            right_part = s[i:]
            left_len = solve(left_part)
            right_len = solve(right_part)
            min_len = min(min_len, left_len + right_len + 1)
        return min_len

