import math

def solve(n):
    def f(x, y):
        return x**y * y + y**x * x - n

    def df_dx(x, y):
        return y * (x**y * math.log(x) - n)

    def df_dy(x, y):
        return x * (y**x * math.log(y) - n)

    def newton_raphson(x, y, epsilon=1e-9):
        while True:
            dx = df_dx(x, y)
            dy = df_dy(x, y)
            if abs(dx) < epsilon and abs(dy) < epsilon:
                return x, y
            x_new = x - f(x, y) / df_dx(x, y)
            y_new = y - f(x, y) / df_dy(x, y)
            if abs(x_new - x) < epsilon and abs(y_new - y) < epsilon:
                x, y = x_new, y_new
                continue
            x, y = x_new, y_new

    x, y = 1, 1
    while True:
        x_new, y_new = newton_raphson(x, y)
        if x_new >= 1 and x_new <= n and y_new >= 1 and y_new <= n:
            return x_new, y_new
        x, y = x_new, y_new

    return -1

