import itertools
import re

def solve(s):
    if len(s) % 3 != 0:
        return ":("

    patterns = ['aaa', 'aba', 'bba', 'bbb']
    for pattern in patterns:
        if re.search(pattern, s, re.IGNORECASE):
            return ' '.join(pattern)

    # If no pattern is found, try all possible combinations
    for a, b, c in itertools.product('aaabbb', repeat=3):
        if a + b + c == s and (b >= a and (b >= c or c >= a)) or (b <= a and (b <= c or c <= a)):
            return ' '.join([a, b, c])

    return ":("

