import sys
from functools import lru_cache

def solve(a):
    n = len(a)
    @lru_cache(None)
    def dp(i):
        if i == n:
            return 0
        res = float('inf')
        for j in range(i, n):
            res = min(res, abs(int(a[i] + a[j]) + dp(j + 1)))
        return res

    return ''.join(('+' if x > 0 else '-') for x in dp(1))

