def solve():
    def xor(a):
        return reduce(lambda x, y: x ^ y, a)

    def swap_bits(a, i, j, b):
        mask = (1 << b) - 1
        return [(a[i] ^ (mask << (b+1))) | (a[j] & ~mask), (a[j] ^ (mask << (b+1))) | (a[i] & ~mask)]

    def solve_internal(a):
        if len(a) == 1:
            return a[0]
        xor_val = xor(a)
        for i in range(len(a)):
            for j in range(i+1, len(a)):
                for b in range(len(bin(a[i])) - 2, -1, -1):
                    a[i], a[j] = swap_bits(a, i, j, b)
                    if xor(a) > xor_val:
                        xor_val = xor(a)
                    a[i], a[j] = a[j], a[i]
        return xor_val

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
