        return (sum(a) % m + m) % m

    def solve_subarray(a, low, high):
        if low == high:
            return 0 if a[low] % 2 == 0 else 1
        mid = (low + high) // 2
        left = solve_subarray(a, low, mid)
        right = solve_subarray(a, mid + 1, high)
        if sum_mod(accumulate(a[mid:high + 1]), 2) == 0:
            return min(left, right)
        else:
