def solve():
    def divide_and_conquer(arr, start, end):
        if start == end:
            return 0 if sum(arr) % 2 == 0 else 1

        mid = (start + end) // 2
        left_sum = divide_and_conquer(arr, start, mid)
        right_sum = divide_and_conquer(arr, mid + 1, end)

        if left_sum + right_sum > left_sum + (right_sum - left_sum) // 2:
            return left_sum + (right_sum - left_sum) // 2
        else:
            return left_sum + right_sum

    while True:
        try:
            n = int(input())
            a = list(map(int, input().split()))
            print(divide_and_conquer(a, 0, len(a) - 1))
        except EOFError:
            break

