def solve(b, s):
    total = sum(b)
    if total != s:
        return "NO"

    missing = s - total
    candidates = set(range(1, len(b) + 1)) - set(b)
    if missing not in candidates:
        return "NO"

    perms = list(permutations(candidates))
    for perm in perms:
        if sum(perm) == missing:
            result = b + list(perm)
            result.sort()
            return "YES"

    return "NO"

