import functools

def solve(s):
    count = Counter(s)
    n = len(s)
    double_count = {k: v * 2 for k, v in count.items()}
    odd_count = sum(1 for k, v in double_count.items() if v % 2 != 0)

    if odd_count > 1:
        return "Impossible"
    elif odd_count == 1:
        mid = n // 2
        for k in double_count:
            if double_count[k] > 1:
                double_count[k] -= 2
            else:
                double_count[k] = 0
                mid -= 1
        middle = functools.reduce(lambda x, y: x + y, double_count.values(), "")
        return middle + middle[::-1] + (s[mid] if odd_count else "") + middle[::-1]
    else:
        return "".join(functools.reduce(lambda x, y: x + y * 2, s, "")[::-1])

