        rooks = [list(map(int, input().split())) for _ in range(m)]

        # Initialize a visited list and a deque to store possible moves for each rook
        visited = [[False] * n for _ in range(n)]
        moves = [[collections.deque() for _ in range(n)] for _ in range(n)]

        # Fill the deque with possible moves for each rook
        for r, c in rooks:
            for i in range(r + 1, n):
                moves[i][c].append((i, c))
            for j in range(c + 1, n):
                moves[r][j].append((r, j))

        # Check if it's possible to move one rook without attacking another
        for comb in itertools.combinations(range(m), 2):
            r1, c1 = rooks[comb[0]]
            r2, c2 = rooks[comb[1]]
            if not (r1 == r2 or c1 == c2):
                if not (moves[r1][c1] and moves[r2][c2]):
                    print("NO")
                    break

        # If no conflict was found, find a rook that can move to an unoccupied cell
        for i in range(m):
            r, c = rooks[i]
            for move in moves[r][c]:
                if not visited[move[0]][move[1]]:
                    visited[move[0]][move[1]] = True
                    for j in range(m):
                        if rooks[j] != (move[0], move[1]):
                            if moves[rooks[j][0]][rooks[j][1]]:
                                visited[move[0]][move[1]] = False
                                break
                    else:
                        print("YES")
                        break

        # If no rook can move to an unoccupied cell without attacking another, print "NO"
        else:
            print("NO")

