        size_score = 0
        for c in reversed(size):
            size_score += size_map[c]
        return size_score

    a_score = size_compare(a)
    b_score = size_compare(b)

    if a_score < b_score:
        return '<'
    elif a_score > b_score:
        return '>'
    else:
        return '='

import re

def compare_sizes(a, b):
    a_size, b_size = a.upper(), b.upper()
    a_type, a_degree = a_size[0], len(a_size) - a_size[1:].count('X')
    b_type, b_degree = b_size[0], len(b_size) - b_size[1:].count('X')

    if a_type == 'M' and b_type not in ('M', 'S', 'L'):
        return '<'
    elif b_type == 'M' and a_type not in ('M', 'S', 'L'):
        return '>'
    elif a_type == 'S' and b_type == 'S':
        return a_degree < b_degree and '<' or '>'
    elif a_type == 'L' and b_type == 'L':
        return a_degree > b_degree and '>' or '<'
    elif a_type == 'S' and b_type in ('M', 'L'):
        return '<'
    elif a_type == 'L' and b_type in ('M', 'S'):
        return '>'
    elif a_type == 'M' and b_type == 'S':
        return '<' if a_degree < b_degree else '>'
    elif a_type == 'M' and b_type == 'L':
        return '>' if a_degree > b_degree else '<'
    else:
        assert False, f"Invalid T-shirt sizes: {a_size} and {b_size}"

def solve():
    t = int(input())
    for _ in range(t):
        a, b = input().split()
        print(compare_sizes(a, b))

