def solve():
    n = int(input())
    rectangles = defaultdict(list)
    for _ in range(n):
        a, b = map(int, input().split())
        rectangles[a].append(b)
        rectangles[b].append(a)

    edges = []
    for k, v in rectangles.items():
        for i in range(1, len(v)):
            x, y = v[i-1], v[i]
            edges.append((math.gcd(x, y), x, y))

    edges.sort()
    parent = list(range(max(rectangles.keys()) + 1))

    mst_cost = 0
    for _, x, y in edges:
        if find(x) != find(y):
            union(x, y)
            mst_cost += x + y - 2 * math.gcd(x, y)

    perimeter = 0
    for k, v in rectangles.items():
        if len(v) == 1:
            perimeter += k * 2
        else:
            root = find(v[0])
            for i in range(1, len(v)):
                perimeter += math.gcd(v[i], v[0]) * 2
            perimeter += parent[root] * 2

    print(perimeter + mst_cost)

