    slices = defaultdict(int)
    for _ in range(n):
        a, b = map(int, input().split())
        slices[a * b] += 1
        slices[a] += 1
        slices[b] += 1

    min_perimeter = max(slices.keys())
    max_perimeter = sum(slices.values()) * 4

    while min_perimeter < max_perimeter:
        mid_perimeter = (min_perimeter + max_perimeter) // 2
        total_slices = 0
        for perimeter in slices.keys():
            if perimeter <= mid_perimeter:
                total_slices += slices[perimeter]
        if total_slices * 4 <= mid_perimeter:
            max_perimeter = mid_perimeter
        else:
            min_perimeter = mid_perimeter + 1

    print(min_perimeter)

