        b = list(map(int, input().split()))

        # Calculate the XOR of both arrays
        xor = list(accumulate([a[i] ^ b[i] for i in range(n)], func=lambda x, y: x ^ y))

        # Find the index where XOR changes from 0 to 1 or vice versa
        for i in range(1, n):
            if xor[i] != xor[i - 1]:
                break
        else:
            i = n

        # Find the minimum number of swaps required to make the prefix sums equal
        swaps = float('inf')
        for perm in permutations(range(i)):
            new_a = [a[perm[i]] for i in range(n)]
            new_xor = list(accumulate([new_a[i] ^ b[i] for i in range(n)], func=lambda x, y: x ^ y))
            if new_xor[i] == 0:
                swaps = min(swaps, sum(map(abs, list(zip(perm, range(n))))) + (i - 1))

        print(swaps)

