def segment_tree_build(a, n):
    if n == 1:
        return [a[0]]

    size = 2 * n - 1
    squares_size = size // 2
    squares = segment_tree_build(a, squares_size)
    tree = [0] * size

    for i in range(squares_size):
        tree[i] = a[i] * squares[i]
        tree[i + squares_size] = a[i + squares_size] * squares[i]

    for i in range(squares_size - 1, -1, -1):
        tree[i] = tree[2 * i + 1] * tree[2 * i + 2]

    return tree

def segment_tree_query(tree, n, i, j, l, r, prod):
    if j < l or r < i:
        return 0

    if l <= i and r >= j:
        return tree[i] * prod

    mid = (i + j) // 2
    p1 = segment_tree_query(tree, n, mid + 1, j, l, r, prod)
    p2 = segment_tree_query(tree, n, i, mid, l, r, prod)

    return p1 * p2

def segment_tree_update(tree, n, i, j, v, k, x):
    if j < k or r > k:
        return

    if i == k and j == k:
        tree[i] = x
        return

    mid = (i + j) // 2
    segment_tree_update(tree, n, mid + 1, j, k, x)
    segment_tree_update(tree, n, i, mid, k, x)
    tree[i] = tree[i * 2] * tree[i * 2 + 1]

