           list(range((M + 1) * 3 + 1, (M + 1) * 4)) + list(range((M + 1) * 4 + 1, (M + 1) * 5)) + \
           list(range((M + 1) * 5 + 1, (M + 1) * 6)) + list(range((M + 1) * 6 + 1, (M + 1) * N + 1))

    def merge(a, b):
        return [min(x, y) for x, y in zip(a, b)] + [max(a[-1], b[-1])]

    dominoes = []
    for i in range(N - 1):
        for j in range(i + 1, N):
            if abs(grid[i * M + min(M, j * M)] - grid[j * M + min(M, i * M)]) == 1:
                dominoes.append(sorted([grid[i * M + min(M, j * M)], grid[j * M + min(M, i * M)]]))

    return len( list(set(reduce(merge, dominoes, []))) )

