            if 0 <= nx < 2 and 0 <= ny < 2 and (nx, ny) not in visited:
                visited.add((nx, ny))
                q.append((nx, ny, r[ny][nx]))
                if r[ny][nx] == c:
                    visited.update((nx + dx, ny + dy) for dx, dy in d)

    comp1, comp2 = set(), set()
