    for _ in range(t):
        n, k = map(int, input().split())
        if n % 2 != 0:
            print("Invalid input: n should be even.")
            continue

        checked = {}
        pairs = []

        if n % 4 == 0:  # If n is a multiple of 4, the pair (n/4, n/4) always works
            pairs.append((n // 4, n // 4))
            n -= 4

        while n > 0:
            target = (k * (n % 2) + 4) // 4
            for candidate in checked:
                if checked[candidate] == target:
                    pairs.append((candidate, n // 2))
                    pairs.append((n, candidate))
                    break

            if target not in checked:
                checked[n] = target
            n -= 2

        if len(pairs) == n // 2:
            print("YES")
            for pair in pairs:
                print(*pair)
        else:
            print("NO")

