def neighbors(x, y, n, m, board):
    options = [(x + dx, y + dy) for dx, dy in [(0, 1), (1, 0)]]
    return [(nx, ny) for nx, ny in options if 0 <= nx < n and 0 <= ny < m and ( board[(nx, ny)] == '.' or board[(nx, ny)] == 'Y')]

def game_winner(x, y, board, burenka):
    if x == 0 or x == board_dim[0] or y == 0 or y == board_dim[1]:
        return board[x][y] == burenka

    board[x][y] = burenka
    wins = 0
    for nx, ny in neighbors(x, y, *board_dim):
        if game_winner(nx, ny, board, not burenka):
            wins += 1

    board[x][y] = '.'
    if burenka and wins % 2 == 0:
        return True
    elif not burenka and wins > 0:
        return True
    return False

