import collections

def is_valid_move(r, c, n, m):
    return 0 <= r < n and 0 <= c < m

def possible_moves(r, c, n, m):
    moves = []
    if is_valid_move(r, c + 1, n, m):
        moves.append((r, c+1))
    if r and is_valid_move(r-1, c, n, m):
        moves.append((r-1, c))
    for _ in range(3, min(r+1, c+2)+1, 2):
        if is_valid_move(r, c+\_-\_//2, n, m):
            moves.append((r, c+\_-\_//2))
        if r and is_valid_move(r-\_-\_//2, c, n, m):
            moves.append((r-\_-\_//2, c))
    return moves

def bfs(r, c, n, m):
    queue = collections.deque([(r, c, 0, 1)])
    visited = set(((r, c),))
    while queue:
        r, c, length, player = queue.popleft()
        for new_r, new_c in possible_moves(r, c, n, m):
            if (new_r, new_c) == (r-1, c):
                if player == 2:
                    return player
            if (new_r, new_c) not in visited:
                visited.add((new_r, new_c))
                queue.append(((new_r, new_c), length+1, player*(-1)**(length+1))
    return 2 if player == 1 else 1

