from itertools import combinations

def swap(lst, i, j):
    return list(lst[:i] + [lst[j]] + lst[i:j] + [lst[i]] + lst[j:])

def invert(lst):
    return [i for i in range(len(lst))] if lst == list(range(len(lst))) else [lst[i] for i in range(len(lst))]

def solve(lst, fixedness=0):
    if len(lst) == 2:
        return [[1, 2], [2, 1]]
    chains = []
    for i, j in combinations(range(len(lst)), 2):
        if i == j or i == 0 or j == 0:
            continue
        new_lst = swap(lst, i, j)
        new_fixedness = (fixedness + 1 - lst.index(i) - lst.index(j)) % len(lst)
        if new_fixedness < fixedness:
            new_chain = solve(new_lst, new_fixedness)
            chains.append(new_chain)
    return chains if chains else []

