def solve():
    q = collections.deque([(0, bin(n).count('1'), [i for i in range(1, n+1)])])
    next_fix = {}
    while q:
        fixedness, current_permutation, _ = q.popleft()
        if len(q) < fixedness:
            next_fix[fixedness] = (current_permutation, len(q))
        for perm in itertools.permutations(current_permutation):
            if all(perm[i] != i for i in range(n)):
                swapped_perm = list(current_permutation)
                for i, j in zip(range(n), itertools.dropwhile(lambda x: x == j, range(n)[1:] + [0])):
                    swapped_perm[i], swapped_perm[j] = swapped_perm[j], swapped_perm[i]
                q.append((sum(swapped_perm == range(1, n+1)), bin(sum(swapped_perm == range(1, n+1))).count('1'), swapped_perm))

    max_chain_len = max(next_fix.keys())
    current_chain = []
    current_permutation = next_fix[max_chain_len][0]
    current_chain.append((0, current_permutation))

    while current_chain[-1][0] < len(next_fix[max_chain_len][1]):
        _, current_permutation = next_fix[max_chain_len - current_chain[-1][0]][1:]
        current_chain.append((current_chain[-1][0] + 1, current_permutation))

