import functools

@functools.lru_cache(maxsize=None)
def min_moves(n, memo={}):
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    if n < 0:
        return float('inf')
    min_moves_2 = min_moves(n - 2, memo) + 1 if min_moves(n - 2, memo) != float('inf') else float('inf')
    min_moves_3 = min_moves(n - 3, memo) + 1 if min_moves(n - 3, memo) != float('inf') else float('inf')
    min_moves_val = min(min_moves_2, min_moves_3)
    memo[n] = min_moves_val
    return min_moves_val

