def bfs(grid, x1, y1, x2, y2):
    direction = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = set()
    queue = [(0, x1, y1)]  # initial energy and position

    while queue:
        energy, x, y = heapq.heappop(queue)

        if (x, y) in visited:
            continue

        visited.add((x, y))

        if x == x2 and y == y2:
