class MinUniquePrefix:
    def __init__(self):
        self.num_unique = 0
        self.moves = 0
        self.sequence = []

    def add(self, num: int):
        while self.num_unique < len(self.sequence) and self.sequence[-1] == num:
            if len(self.sequence) - self.moves > num:
                self.moves += 1
            self.sequence.pop()
            self.num_unique -= 1
        self.sequence.append(num)
        self.num_unique += 1

