from collections import defaultdict, deque

def neighbors(x, y):
    return [(x-1, y), (x+1, y), (x, y+1), (x, y-1)]

def dfs(x, y, visited, dist, grid):
    if (x, y) in visited or grid[(x, y)] == 0:
        return float('inf')

    visited.add((x, y))
    visited_boxes = visited.copy()
    dist[0] = 0

    queue = deque([((x, y), [])])

    while queue:
        cx, cy, _ = queue.popleft()
        for nx, ny in neighbors(cx, cy):
            if (nx, ny) not in visited:
                visited.add((nx, ny))

                if grid[(nx, ny)] == -1:
                    dist[0] += 1

                grid[(nx, ny)] = -1
                queue.append(((nx, ny), dist[:]))

    # Backtrack and update minimum distance
    while visited_boxes:
        pop_idx = visited_boxes.pop()
        x, y = pop_idx
        distance = dist[pop_idx] + dist[-1]

        if grid[pop_idx] == -1:
            distance -= 1

        if distance < dist[0]:
            dist[:] = list(reversed(dist[pop_idx : ])) + dist[:pop_idx]
            dist[0] = distance

def solve(grid):
    n = len(grid) + len([x for x in grid if x])
    dist = [float('inf')] * (n+1)
    visited = set()

    dfs(0, 0, visited, dist, grid)

    return dist[0] if dist[0] != float('inf') else -1

