import itertools
from functools import lru_cache

@lru_cache(maxsize=5242880)  # Cache with 5MB for larger tests
def lcm(x, y):
    return abs((x * y).reduced())

def solve(n):
    perms = list(itertools.permutations(range(1, n+1)))  # Generates all permutations
    dp = [[0] * n for _ in range(n)]  # Dynamic programming array

    # Precompute LCM as a prefix for each position and perm
    for i, perm in enumerate(perms):
        dp[i][0] = lcm(perm[0], 1)
        for j in range(1, n):
            dp[i][j] = lcm(perm[j], dp[i][j-1])

    # Find suffix with maximum sum for each position and choose the final answer
    for i in range(1, n):
        max_sum = 0
        index = -1
        for j, perm in enumerate(perms):
            if j >= i and dp[j][i] > max_sum:
                max_sum = dp[j][i]
                index = j
        dp[-1][i] = max_sum  # Store the maximum sum for n-1 suffixes

    # Generate the final answer by choosing the prefix with maximum sum at each position
    answer = []
    for i in range(n-1, -1, -1):
        index_prefix = dp[index][i] == dp[-1][i] and index or perms[index][i]
        answer.append(index_prefix)
        index = perms.index((index_prefix,) + answer)

    return answer[::-1]  # Reverse the list to get the permutation in the correct order

