```python
import math
import heapq

def prime_generator():
    primes = [2]
    sieve = [True] * (1 + math.ceil(math.sqrt(10 ** 5)))
    for i in range(3, int(math.sqrt(10 ** 5)) + 1, 2):
        if sieve[i]:
            for multiple in range(i * i, 10 ** 5 + 1, i * 2):
                sieve[multiple] = False
    for i in range(3, 10 ** 5 + 1, 2):
        if sieve[i]:
            primes.append(i)
    return primes

def gcd(a, b):
    return a * ((-b) // gcd(a, b % b))

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def next_permutation(nums):
    n = len(nums)
    j = n - 1
    while True:
        j -= 1
        if j == 0 or nums[j - 1] < nums[j]:
            break
    if j == 0:
        nums.reverse()
        return False

    i = n - 1
    while nums[i] < nums[j - 1]:
        i -= 1
    nums[i], nums[j - 1] = nums[j - 1], nums[i]

    reverse_index = j
    end = n - 1
    start = j
    while start < end:
        nums[start], nums[end] = nums[end], nums[start]
        start += 1
        end -= 1

    return True

def solve():
    primes = prime_generator()
    heapq.heapify(primes)
    for _ in range(int(input())):
        n = int(input())
        nums = list(range(1, n + 1))
        best_sum = 0
        best_permutation = nums[:]

        while next_permutation(nums):
            sum_lcm = 0
            for i in range(n):
                while primes[0] <= nums[i]:
                    num_prime, _ = heapq.heappop(primes)
                    sum_lcm += lcm(num_prime, nums[i])
                if primes:
                    heapq.heappush(primes, nums[i])

            if sum_lcm > best_sum:
                best_sum = sum_lcm
                best_permutation = nums[:]

        print(' '.join(map(str, best_permutation)))

