Here's the Python code that uses the Hungarian algorithm from the `networkx` library:

```python
import networkx as nx
import sys
import numpy as np

def edge_weight(u, v):
    return u

def create_graph(n):
    G = nx.Graph()
    for i in range(1, n+1):
        for j in range(1, i+1):
            if i % j == 0:
                G.add_edge(i, j)
    return G

def hungarian(G):
    match = nx.minimum_weight_bipartite_matching(G)
    perm = list(match.keys()) + list(match.values())
    perm.sort()
    return perm

def solve():
    n = int(input())
    for _ in range(n):
        graph = create_graph(int(input()))
        min_weight_permutation = hungarian(graph).tolist()
        sys.stdout.write(' '.join(map(str, min_weight_permutation)) + '\n')

from functools import reduce
from math import gcd

def mobius(n):
    mo = [0] * (n + 1)
    for i in range(1, n + 1):
        for k in range(i, n + 1, i):
            mo[k] -= mo[k] // i
    return mo

def inverse(mo):
    inv = [0] * (n + 1)
    inv[1] = 1
    for k in range(2, n + 1):
        for i in range(k, n + 1, k):
            inv[i] = (inv[i] + inv[i // k] * mo[k]) % phi
    return inv

def phi(n):
    return reduce((lambda a, x: a * (x - x // x) if x > 1 else a), range(1, n + 1))

def solve(n):
    mo = mobius(n)
    phi_n = phi(n)
    inv = inverse(mo)
    p = [0] * n
    for i in range(1, n + 1):
        p[i - 1] = (inv[i] * phi_n) % i
    return p

