def find_permutation(n):
    w = [[0] * n for _ in range(n)]
    primes = [i for i in range(2, n + 1) if is_prime(i)]
    for i in range(1, n + 1):
        w[i - 1][i - 1] = 1 if i == 1 else 0
        for j in range(i, n):
            w[i - 1][j] = min(w[i - 1][j - 1] + (j % i != 0), w[i][j])
    min_permutation = []
    for i in range(n - 1, -1, -1):
        idx = min([j for j in range(i + 1, n) if w[i][j] == w[i - 1][i] - 1], key=lambda j: primes[j] * (n // j) - primes[i] * (j // i))
        min_permutation.append(idx + 1)
        min_permutation.append(i + 1)
    return min_permutation[::-1]

