import sys
import heapq

def dijsktra(arr, src):
    inf = float('inf')
    dist = [inf] * len(arr)
    dist[src] = 0
    q = [(0, src)]

    while q:
        d, u = heapq.heappop(q)

        if dist[u] < d:
            continue

        for v, w in enumerate(arr[u:]):
            if v + 1 > u:
                heapq.heappush(q, (d + w, v + 1))
                dist[v + 1] = min(dist[v + 1], d + w)

    return dist[len(arr) - 1] != inf

