from collections import defaultdict
import sys

def dfs(idx, current_sum, diff_dict, array):
    if idx > len(array):
        return True

    needed = array[idx] - current_sum

    if needed not in diff_dict:
        return False

    diff_count = diff_dict[needed]
    if diff_count == 0:
        return False

    diff_dict[needed] -= 1
    result = dfs(idx + 1, current_sum, diff_dict, array)
    diff_dict[needed] += 1

    if result:
        return True

    for i in range(1, needed):
        if diff_dict.get(i, 0) > 0:
            diff_dict[i] -= 1
            result = dfs(idx + 1, current_sum + i, diff_dict, array)
            diff_dict[i] += 1

    return result

