import string
from collections import defaultdict, deque

def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        a = list(map(int, input().split()))
        s = string.ascii_uppercase * m
        graph = defaultdict(list)
        for i, a_i in enumerate(a):
            graph[s[a_i - 1]].append(s[m + 1 - a_i])
            graph[s[m + 1 - a_i]].append(s[a_i - 1])

        def dfs(i, str_so_far, visited):
            if i >= n:
                if not any(visited[x] for x in visited):
                    print(str_so_far)
                return

            for c in graph[str_so_far[i - 1]]:
                if c not in visited:
                    visited[c] = str_so_far[i - 1]
                    dfs(i + 1, str_so_far[:i] + c + str_so_far[i:], visited.copy())
                    visited[c] = None

        q = deque([('A', {}, [])] + [('B', visited, [x for x in s if x != visited[x]]) for x in s if x != visited[x]])
        while q:
            char, visited, nodes_to_visit = q.popleft()
            dfs(1, char * nodes_to_visit, visited)
            for c in graph[char]:
                if c not in visited:
                    ntv = list(nodes_to_visit) + [x for x in nodes_to_visit if x == c]
                    q.append((c, visited | {c: char}, ntv))

