import itertools

def can_arrange(heights, n, x):
    def dfs(front_stack, back_stack, front_i, back_i):
        if front_i == n:
            # If we have successfully filled the first row, check if the heights meet the requirements
            if back_stack and all(back_[i] >= front_[i] + x for i, back_ in enumerate(back_stack) for _ in range(n) if back_[i]):
                return True
            return False

        for candidate in range(front_i, 2 * n):
            if not front_stack or front_stack[-1] < heights[candidate]:
                front_stack.append(heights[candidate])
                dfs(front_stack, back_stack, front_i + 1, back_stack + [front_stack[:]] if back_i == n else back_stack)
                front_stack.pop()

    # Iterate through all possible arrangements of the first row
    return any(dfs([], [], 0, n) for _ in itertools.permutations(heights[::2], n))

