from collections import defaultdict

def solve(n, s, memo={}):
    if n in memo:
        return memo[n]
    if n == 0:
        return 0
    if len(s) == 1:
        return 1 if s[0] not in memo else memo[s[0]]

    result = s[0] not in memo and 1 + solve(n - 1, s[1:], memo) or solve(n - 1, s[1:], memo)
    for i in range(1, n):
        if s[i] > s[i - 1] and s[i] not in memo:
            result = max(result, 1 + solve(n - i, s[i:], memo))
    memo[n] = result
    return result

