def solve(n):
    if n <= 1:
        return 0, [str(i + 1) for i in range(n)]

    costs, perms = [], []
    combs = list(itertools.permutations(range(1, n + 1)))
    for c in range(1, n):
        possibilities = [(cmb[i + 1] // c, cmb[i]) for i in range(n - 1) if cmb[i] < cmb[i + 1]]
        for p, last in possibilities:
            current_cost = 0
            new_comb = list(cmb)
            while last != new_comb[-1]:
                new_comb[new_comb.index(p)] = new_comb[-1]
                current_cost += 1
                new_comb[-1] = last
            costs.append((current_cost + len([pair for pair in possibilities if pair[1] * c == pair[0]]), new_comb))

    costs.sort(reverse=True)
    return costs[0][0], ' '.join(str(i + 1) for i in costs[0][1])

import math
import functools

@functools.lru_cache(maxsize=None)
def factorial(n):
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

@functools.lru_cache(maxsize=None)
def inv(n, mod):
    for x in range(1, mod):
        if (n * x) % mod == 1:
            return x
    return 1

def power(a, b, mod):
    if b == 0:
        return 1
    if b % 2 == 1:
        return (a * power(a, b - 1, mod)) % mod
    res = power(a, b // 2, mod)
    return (res * res) % mod

def solve(n):
    if n == 2:
        return 2, [1, 2]

    max_cost = 0
    max_cost_perm = [0] * n
    for i in range(2, int(math.log2(n)) + 2):
        d = power(2, n // i - 1, n)
        cost = 1 + (n - 1) // i
        comb = factorial(n) // (factorial(i) * factorial(n - i))
        if int(comb * cost * power(d, comb, n)) > max_cost:
            max_cost = int(comb * cost * power(d, comb, n))
            max_cost_perm[::] = [0] * n
            max_cost_perm[::i] = list(range(1, i + 1))
            max_cost_perm[i:] = reversed(max_cost_perm[::i])

    inv_n = inv(n, n - 1)
    for i in range(2, n):
        d = power(i, inv_n, n)
        cost = 1 + (n - 1) // i
        comb = factorial(n) // (factorial(i) * factorial(n - i))
        if int(comb * cost * power(d, comb, n)) > max_cost:
            max_cost = int(comb * cost * power(d, comb, n))
            max_cost_perm[::] = [0] * n
            max_cost_perm[::i] = list(range(1, i + 1))
            max_cost_perm[i:] = reversed(max_cost_perm[::i])

    return max_cost, max_cost_perm

