from heapq import heappush, heappop

def dijkstra(a):
    n = len(a)
    dist = [float('inf')] * n
    dist[0] = 0
    queue = []
    heappush(queue, (0, 0))

    while queue:
        d, i = heappop(queue)

        if dist[i] < d:
            continue

        for j in range(n):
            if a[i][j] == 1 and i + j + 1 == n:
                if dist[i] + 1 < dist[j]:
                    dist[j] = dist[i] + 1
                    heappush(queue, (dist[j], j))
            elif a[i][j] == 1:
                if dist[i] + 1 < dist[j] + 1:
                    dist[j] = dist[i] + 1
                    heappush(queue, (dist[j], j))
                if dist[j] < dist[i + 1]:
                    dist[i + 1] = dist[j]
                    heappush(queue, (dist[i + 1], i + 1))

    return dist[-1]

