        dp[0][0] = table[0][0]

        for i in range(1, n):
            for j in range(m):
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + table[i][j])
                if j + 1 < m:
                    dp[i][j + 1] = min(dp[i][j + 1], dp[i - 1][j] + table[i][j + 1])

        for j in range(1, m):
            for i in range(n - 1, -1, -1):
                dp[i][j] += min(dp[i + 1][j], dp[i][j - 1])

        stdout.write(f"{dp[-1][-1]\n}")

from sys import stdin, setrecursionlimit
setrecursionlimit(100000)

def solve(n, m):
    dp = [[0] * m for _ in range(n)]
    for i in range(1, n):
        dp[i][0] = dp[i - 1][0] + (i * m)
    for j in range(1, m):
        dp[0][j] = dp[0][j - 1] + (j)

    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + ((i * m) + j)

    return dp[n - 1][m - 1]

from the cell (1, 1) to the cell (n, m) using Dynamic Programming with memoization. The adjacency map is used to determine the valid adjacent cells.

```python
import collections

def solve(n, m, adj, memo={}):
    key = (n, m)

    if key in memo:
        return memo[key]
    elif n == 1 and m == 1:
        return 0
    elif n == 1 or m == 1:
        return float('inf')
    else:
        cost = float('inf')
        for next_n, next_m in adj[(n, m)]:
            cost = min(cost, solve(next_n, next_m, adj, memo) + (n - 1) * m + next_m)
        memo[key] = cost

    return cost
